import os, time
import click
from click.shell_completion import shell_complete

class Hanging(Option := click.Option):
    def set_state(self, ctx, param, value):
        ctx.call_on_close(lambda: time.sleep(30))
        return value
    def __init__(self, *args, **kwargs):
        kwargs.setdefault("is_eager", True)
        kwargs.setdefault("expose_value", False)
        kwargs.setdefault("callback", self.set_state)
        super().__init__(*args, **kwargs)

@click.group()
@click.option("--hang", cls=Hanging, hidden=True)
def cli():
    pass

@cli.command()
def sub():
    pass

env = {"COMP_WORDS": "cli --hang sub", "COMP_CWORD": "2"}

def run(ctx_args):
    for k, v in env.items():
        os.environ[k] = v
    start = time.monotonic()
    rv = shell_complete(cli, dict(ctx_args), "cli", "_CLI_COMPLETE", "bash_complete")
    return rv, time.monotonic() - start

rv, elapsed = run({"cleanup_timeout": 0.5})
print(f"with cleanup_timeout=0.5: rv={rv} elapsed={elapsed:.2f}s")
assert rv == 0 and elapsed < 5

# without timeout it should hang -> verify by timing only briefly via subprocess
print("completion cleanup timeout OK")
